@import "@fontsource-variable/figtree";
@import "@fontsource-variable/jetbrains-mono";

/* Light (faithful): powder page #f3f4f1, white cards, ink #0a0b0b, deep violet #311164 bands,
   soft violet #ceb4fa buttons, pale violet #f3edfe callouts, bright violet #8a4ef4 hover text,
   spring green #50faab for the logo mark and mint surfaces, greige #e4e3dc chips. */
:root {
  --background: #f3f4f1;
  --foreground: #0a0b0b;
  --card: #ffffff;
  --card-foreground: #0a0b0b;
  --popover: #ffffff;
  --popover-foreground: #0a0b0b;
  --primary: #311164;
  --primary-foreground: #ffffff;
  --secondary: #ceb4fa;
  --secondary-foreground: #0a0b0b;
  --muted: #e4e3dc;
  --muted-foreground: #5d5e5d;
  --accent: #f3edfe;
  --accent-foreground: #0a0b0b;
  --destructive: #c2410c;
  --destructive-foreground: #ffffff;
  --border: rgb(10 11 11 / 11%);
  --input: rgb(10 11 11 / 22%);
  --ring: #8a4ef4;
  --highlight: #8a4ef4;
  --highlight-foreground: #ffffff;
  --glow: #50faab;
  --chart-1: #311164;
  --chart-2: #8a4ef4;
  --chart-3: #50faab;
  --chart-4: #ceb4fa;
  --chart-5: #8a4b08;
  --sidebar: #f5f5f1;
  --sidebar-foreground: #0a0b0b;
  --sidebar-primary: #311164;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f3edfe;
  --sidebar-accent-foreground: #0a0b0b;
  --sidebar-border: rgb(10 11 11 / 11%);
  --sidebar-ring: #8a4ef4;

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  /* includes the gutters: 87rem − 2 × 1.75rem ≈ the original's 1332px column */
  --page-width: 87rem;
  --page-gutter: 1.75rem;
  --section-y: 4rem;
}

/* Dark sibling: a violet-black night page, violet-tinted panels, the same violets and green. */
.dark {
  --background: #0f0b18;
  --foreground: #f3f4f1;
  --card: #1a1426;
  --card-foreground: #f3f4f1;
  --popover: #1a1426;
  --popover-foreground: #f3f4f1;
  --primary: #3d1a78;
  --primary-foreground: #ffffff;
  --secondary: #ceb4fa;
  --secondary-foreground: #0a0b0b;
  --muted: #2a2338;
  --muted-foreground: #b3afbd;
  --accent: #241a3a;
  --accent-foreground: #f3f4f1;
  --destructive: #f97316;
  --destructive-foreground: #0a0b0b;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 20%);
  --ring: #a77bf7;
  --highlight: #b28cf8;
  --highlight-foreground: #0a0b0b;
  --glow: #50faab;
  --chart-1: #ceb4fa;
  --chart-2: #a77bf7;
  --chart-3: #50faab;
  --chart-4: #8a4ef4;
  --chart-5: #f0b46a;
  --sidebar: #140f20;
  --sidebar-foreground: #f3f4f1;
  --sidebar-primary: #ceb4fa;
  --sidebar-primary-foreground: #0a0b0b;
  --sidebar-accent: #241a3a;
  --sidebar-accent-foreground: #f3f4f1;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #a77bf7;
}
